INSERT INTO sources (id, manufacturer, title, url, published_date, accessed_date, source_type, notes) VALUES
  ('ford-ranger-super-duty-au', 'Ford Australia', 'Ford Ranger Super Duty', 'https://www.ford.com.au/showroom/trucks-and-vans/ranger/super-duty/', NULL, '2026-08-17', 'manufacturer_webpage', 'Official product page; figures describe maximum or single-cab configuration and exclude tray.'),
  ('toyota-hilux-jun-2026', 'Toyota Australia', 'Toyota HiLux Spec Table June 2026', 'https://www.toyota.com.au/-/media/toyota/main-site/vehicle-hubs/hilux/files/20260630_hilux_spec_sheet_gto010060.pdf?rev=d222769888af49519347727deb13bb73', '2026-06-30', '2026-08-17', 'manufacturer_pdf', 'Official Australian specification table. Toyota labels weights approximate.'),
  ('isuzu-dmax-25-5my', 'Isuzu UTE Australia', '25.5MY Isuzu D-MAX Specifications', 'https://cdn-iua.dataweavers.io/-/media/d-max/documents/25-5my-isuzu-d-max-vehicle-specifications.pdf?rev=30680420a74d44c9af2c12f77ee2d85d', NULL, '2026-08-17', 'manufacturer_pdf', 'Official Australian specification table. Cab-chassis kerb mass excludes tray body.'),
  ('mazda-bt50-payload-au', 'Mazda Australia', 'Mazda BT-50 Payload Calculator', 'https://www.mazda.com.au/cars/bt-50/payload/', NULL, '2026-08-17', 'manufacturer_webpage', 'Official interactive calculator. Publishes bare-chassis and standard-tray-fitted mass states per grade, plus an accessory weight table (canopy 130 kg, bull bar 62-68 kg, suspension upgrade 85-95 kg). Vehicle assets are dated October 2025.'),
  ('mitsubishi-triton-25my-dcc', 'Mitsubishi Motors Australia', 'Triton Cab Chassis - Payload, Towing & Axle Strength', 'https://www.mitsubishi-motors.com.au/blog/2025/payload-towing-and-axle-strength.html', '2025-05-27', '2026-08-17', 'manufacturer_webpage', 'Official model-level figures for 25MY GLX Double Cab Chassis; page says 4x2/4x4 and manual/automatic are available but does not map mass figures to each combination.'),
  ('toyota-lc70-oct-2025', 'Toyota Australia', 'Toyota LC70 Spec Table October 2025', 'https://www.toyota.com.au/-/media/toyota/main-site/vehicle-hubs/lc70/files/20251021_lc70_spec_table_gto009454.pdf?rev=4e4c662a09fe418c9a5a7b00509b16dd', '2025-10-21', '2026-08-17', 'manufacturer_pdf', 'Official Australian specification table. Toyota labels weights approximate.'),
  ('toyota-tundra-may-2026', 'Toyota Australia', 'Toyota Tundra Spec Table May 2026', 'https://www.toyota.com.au/-/media/toyota/main-site/vehicle-hubs/tundra/files/20260506-tundra_spec-table_gto009469-v1.pdf?rev=fe8c44cde59d4c339adb2c9124278b61', '2026-05-06', '2026-08-17', 'manufacturer_pdf', 'Official Australian specification table. Payload is derived from published GVM minus maximum kerb weight.'),
  ('gmsv-silverado-towing-au', 'GMSV', 'Towing With Silverado', 'https://www.gmspecialtyvehicles.com/au-en/chevrolet/trucks/trailering-and-towing', NULL, '2026-08-17', 'manufacturer_webpage', 'Official Australian mass, payload, rear axle, towing and towball figures.'),
  ('kia-tasman-my26-au', 'Kia Australia', 'Kia Tasman Model Year 2026 Brochure', 'https://www.kia.com/content/dam/kwcms/au/en/images/pdf/tasman/kia-tasman-brochure.pdf', NULL, '2026-08-17', 'manufacturer_pdf', 'Official Australian brochure for MY26 dual-cab pickup variants. These are tub vehicles, not cab-chassis records.'),
  ('mercedes-unimog-u4023-au', 'Mercedes-Benz Trucks Australia', 'Unimog U 4023 Extreme Off-road Technical Data', 'https://www.mercedes-benz-trucks.com/au/en/trucks/unimog-offroad.html', NULL, '2026-08-17', 'manufacturer_webpage', 'Current Australian U 4023 page. The page labels 10.3 t as maximum permissible gross combination weight, while context suggests permissible gross vehicle weight; retain as a review issue.'),
  ('iveco-daily-4x4-my24-au', 'IVECO Australia', 'New Daily 4x4 Specification Sheet', 'https://www.iveco.com/au/-/media/IVECOdotcom/Australia/Products/DailyMy24/Brochures/New-Daily-4x4-Spec-Sheet---Web-Version.pdf?rev=0fa977f9dcb94b2a930710f0f71e1b36', NULL, '2026-08-17', 'manufacturer_pdf', 'Official Australian specification sheet. Kerb includes chassis cab, 75 kg driver, full fuel, oils, tools and spare wheel where present.'),
  ('isuzu-nps-75-175-4x4-au', 'Isuzu Australia', 'NPS 75-175 4x4 Specifications', 'https://prd1.isuzu.com.au/media/5rrdsxuw/spec_nps_75_175_4x4_2605_r3.pdf', NULL, '2026-08-17', 'manufacturer_pdf', 'Official current Australian day-cab and crew-cab specification sheet.'),
  ('fuso-canter-4x4-au', 'Fuso Australia', 'Canter 4x4 Wide Cab', 'https://www.fuso.com.au/range/canter/4x4/wide-cab/', NULL, '2026-08-17', 'manufacturer_webpage', 'Official Australian model page; does not publish cab-chassis mass or axle limits.'),
  ('man-tgm-4x4-rv-au', 'MAN Truck & Bus Australia', 'TGM 13.250-290 4x4 BL CH RV Specification', 'https://www.man.com.au/wp-content/uploads/2025/02/TGM-13.250-290-4X4-RV-Spec.pdf', '2025-02-01', '2026-08-17', 'manufacturer_pdf', 'Official Australian RV chassis specification. GCM is listed as 28,000 kg, with 20,000 kg applicable with engageable transfer case; conservative 20,000 kg is stored.'),
  ('iveco-eurocargo-my24-4x4-au', 'IVECO Australia', 'Eurocargo MY24 4x4', 'https://www.iveco.com/au/Eurocargo/Eurocargo-MY24-4x4', NULL, '2026-08-17', 'manufacturer_webpage', 'Official Australian model page; exposes 15,000 kg GVM, 19,000 kg GCM and 3,915/4,150 mm wheelbases at model level.'),
  ('mitsubishi-triton-26my-au', 'Mitsubishi Motors Australia', '26MY Triton Brochure', 'https://www.mitsubishi-motors.com.au/content/dam/mmal/pdfs/vehicle-brochures/26MY%20Triton%20Brochure.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'Official Australian 26MY brochure with a full 14-column Dimensions and Weights table covering 2WD and 4WD, single, club and double cab, in cab-chassis and pick-up bodies. Supersedes the 25MY model-level page.'),
  ('ford-ranger-2022my-au', 'Ford Australia', 'Next-Generation Ranger 2022MY Specifications', 'https://www.ford.com.au/content/dam/ecomm/Release-3/AU/landing/next-gen-ranger-ebrochure-specifications.pdf', NULL, '2026-08-17', 'manufacturer_pdf', 'Official Australian launch specification brochure with per-variant mass tables, verified directly with exact payload arithmetic on every row. CURRENCY WARNING: this is the 2022MY document and the current Australian range is 2026.50MY, so every figure needs refreshing before customer exposure. Rows are source_verified because they were checked against this document; staleness is tracked in the coverage register and row notes, not in verification_status. Ford blocks automated retrieval; obtained manually. The 4x2 section in this document omits its Vehicle Masses page, so only 4x4 masses are recorded.'),
  ('ford-f150-my24-au', 'Ford Australia', 'F-150 MY24 Specification Sheet', 'https://www.ford.com.au/content/dam/Ford/au/nameplate/f-150/brochures/f-150-spec-sheet-my24.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'Official Australian MY24 specification sheet, supplied manually because ford.com.au blocks automated retrieval. Verified directly: GVM, GCM, kerb, payload, front and rear GAWR and wheelbase all match for both the 145-inch/5.5-foot and 157-inch/6.5-foot configurations. Ford states payload is derived by subtracting kerb weight from GVM, so its payload is a calculation. Currency caveat: this is the MY24 sheet while the range is currently listed.'),
  ('ram-1500-au', 'RAM Trucks Australia', 'RAM 1500 Grade Pages', 'https://www.ramtrucks.com.au/vehicles/1500-big-horn-crew-cab/', NULL, '2026-08-18', 'manufacturer_webpage', 'NOT INDEPENDENTLY VERIFIED: the RAM grade pages render client-side with no mass data in the HTML, and the supplied compilation cites a third-party site as its secondary source.'),
  ('ram-2500-3500-au', 'RAM Trucks Australia', 'RAM 2500 and 3500 Laramie Cummins High Output Specification', 'https://resource.digitaldealer.com.au/pdf/211467751697043e181834349841250.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'Official RAM specification brochure, hosted on a dealer resource CDN rather than ramtrucks.com.au. Verified directly, including the optional derating of the 3500 to 4,495 kg GVM and 795 kg payload.'),
  ('nissan-navara-au', 'Nissan Australia', 'All-New Navara Specifications and Pricing', 'https://www.nissan.com.au/vehicles/browse-range/all-new-navara/specs-and-pricing.html', NULL, '2026-08-18', 'manufacturer_webpage', 'Official Australian specifications page. Verified directly for all four grades.'),
  ('vw-amarok-my25-au', 'Volkswagen Group Australia', 'Amarok MY25 Brochure and Specifications', 'https://www.volkswagen.com.au/idhub/content/dam/onehub_pkw/importers/au/pdfs/commercial-vehicles/VW_CV_Amarok_VWCAMAROKMY25_BrochureSpec_Sep25_FA.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'Official Australian MY25 brochure. Verified directly: kerb and payload rows match to the kilogram. Note 2 states Volkswagen derives payload by subtracting kerb weight from GVM, so its published payload is a calculation, not an independent measurement.'),
  ('gwm-cannon-2026-au', 'GWM Australia', 'Cannon 2026 Brochure', 'https://assets.gwmanz.com/f/256395/x/f66059e2b4/y4rt9h-au-cannon-brochure-2026-a4-210x297mm.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'Official Australian 2026 brochure. Verified directly against the kerb weight, payload and GVM rows.'),
  ('gwm-cannon-alpha-au', 'GWM Australia', 'Cannon Alpha Brochure', 'https://assets.gwmanz.com/f/256395/x/43c46a95d0/cannon-alpha-brochure-au.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'Official Australian brochure. Verified directly. Two 3.0 turbo-diesel grades are listed without a mass table and are not recorded.'),
  ('kia-tasman-cab-chassis-au', 'Kia Australia', 'Kia Tasman Cab Chassis Brochure', 'https://www.kia.com/content/dam/kwcms/au/en/images/pdf/tasman/kia-tasman-cab-chassis-brochure.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'Official Australian cab-chassis brochure, separate from the pickup brochure. Verified directly. Kia states kerb weight and payload exclude the weight of tray bodies.'),
  ('ford-ranger-2026-50my-au', 'Ford Australia', 'Ranger 2026.50MY Specifications Brochure', 'https://www.ford.com.au/content/dam/Ford/au/nameplate/ranger/brochure/specs-brochure/2026-50-my-ranger-brochure.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'NOT INDEPENDENTLY VERIFIED: ford.com.au blocks automated retrieval. Figures come from a supplied compilation with page-level locators. IMPORTANT: the stored kerb mass is Ford''s lightest-orderable-equipment figure, which yields the LARGEST payload. On the 2022MY brochure the heavier options figure was up to 68 kg greater. Obtain the brochure and add the heavy-options kerb before any customer exposure.'),
  ('kgm-musso-my26-au', 'KGM Australia', 'Musso and Musso XLV MY26 Specifications and Features', 'https://payload.therefinerydesign.com/api/media/file/KGM-Musso-MY26-Specs-and-Features.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'Official MY26 specification sheet. Verified directly: resolves the previously unattributed 880 kg and 1,010 kg payload configurations as Musso XLV variants.'),
  ('ram-1500-2026-au', 'RAM Trucks Australia', 'RAM 1500 Specification Brochure', 'https://resource.digitaldealer.com.au/pdf/4385833746a1d25a063869361464389.pdf', NULL, '2026-08-18', 'manufacturer_pdf', 'Official RAM specification brochure on a dealer resource CDN. Verified directly. Supersedes the earlier unverified RAM 1500 rows, which had the Rebel and Limited kerb and payload figures wrong.');
INSERT INTO vehicle_variants VALUES
  ('ford-ranger-super-duty-my26-single-cab', 'Ford', 'Ranger Super Duty', 2026, NULL, 'Super Duty', 'single_cab', 'cab_chassis', '4x4', '3.0L V6 turbo-diesel', '10-speed automatic', NULL, 'Check state licence requirements after body fitment and final GVM', NULL, 2518, 'Derived from GVM minus published maximum payload; excludes tray', 4500, 8000, 1900, 2800, 1982, 'Maximum payload; single cab excluding tray', 4500, NULL, NULL, NULL, NULL, 'ford-ranger-super-duty-au', 'Overview and disclosures: Carry more / payload / GAWR', 'source_verified', 0, 'OPTIMISTIC KERB: kerb mass is derived as GVM minus Ford''s published maximum payload, and Ford computes maximum payload against minimum kerb, so the figure is a lightest-equipment kerb and the payload is a best case. Published on the owner''s decision as a guide, with the basis disclosed to the customer on the calculator: Beyond RV weighs the vehicle at the factory before build and those figures decide. Replace with a delivered-variant mass table when Ford publishes one. Cab chassis: kerb excludes the tray, and the calculator asks for the tray weight separately.');
INSERT INTO vehicle_variants VALUES
  ('ford-ranger-2022my-4x4-xl-single-cc-biturbo', 'Ford', 'Ranger', 2022, NULL, 'XL', 'single_cab', 'cab_chassis', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 1903, 'Kerb weight with heaviest factory optional equipment; excludes tray body', 3230, 6350, 1490, 1959, 1327, 'Published payload based on kerb weight; excludes tray body', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XL, XLT 2022MY Vehicle Masses: 4x4 Single Cab Cab-Chassis', 'source_verified', 0, 'Ford also publishes minimum kerb weight 1,835 kg giving 1,395 kg payload; the conservative figure is stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xl-super-cc-biturbo', 'Ford', 'Ranger', 2022, NULL, 'XL', 'super_cab', 'cab_chassis', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2007, 'Kerb weight with heaviest factory optional equipment; excludes tray body', 3230, 6350, 1490, 1959, 1223, 'Published payload based on kerb weight; excludes tray body', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XL, XLT 2022MY Vehicle Masses: 4x4 Super Cab Cab-Chassis', 'source_verified', 0, 'Ford also publishes minimum kerb weight 1,938 kg giving 1,292 kg payload; the conservative figure is stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xl-double-cc-singleturbo', 'Ford', 'Ranger', 2022, NULL, 'XL', 'double_cab', 'cab_chassis', '4x4 part-time', '2.0L single-turbo diesel; 125 kW / 405 Nm', '6-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2046, 'Kerb weight with heaviest factory optional equipment; excludes tray body', 3250, 6200, 1450, 1959, 1204, 'Published payload based on kerb weight; excludes tray body', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XL 2022MY Vehicle Masses: 4x4 Double Cab Cab-Chassis 2.0L Single Turbo', 'source_verified', 0, 'Ford also publishes minimum kerb weight 1,990 kg giving 1,260 kg payload; the conservative figure is stored. Lower GCM of 6,200 kg applies to the single-turbo engine. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xl-double-cc-biturbo', 'Ford', 'Ranger', 2022, NULL, 'XL', 'double_cab', 'cab_chassis', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2072, 'Kerb weight with heaviest factory optional equipment; excludes tray body', 3250, 6350, 1490, 1959, 1178, 'Published payload based on kerb weight; excludes tray body', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XL 2022MY Vehicle Masses: 4x4 Double Cab Cab-Chassis 2.0L Bi-Turbo', 'source_verified', 0, 'Ford also publishes minimum kerb weight 2,003 kg giving 1,247 kg payload; the conservative figure is stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xlt-double-cc-v6', 'Ford', 'Ranger', 2022, NULL, 'XLT', 'double_cab', 'cab_chassis', '4x4 full-time', '3.0L V6 turbo-diesel; 184 kW / 600 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2129, 'Kerb weight with heaviest factory optional equipment; excludes tray body', 3280, 6400, 1490, 1959, 1151, 'Published payload based on kerb weight; excludes tray body', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XLS, XLT 2022MY Vehicle Masses: 4x4 Double Cab Cab-Chassis 3.0L V6', 'source_verified', 0, 'Ford also publishes minimum kerb weight 2,109 kg giving 1,171 kg payload; the conservative figure is stored. Highest GVM (3,280 kg) and GCM (6,400 kg) of the cab-chassis range. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.');
INSERT INTO vehicle_variants VALUES
  ('ford-ranger-2022my-4x4-xl-super-pickup-biturbo', 'Ford', 'Ranger', 2022, NULL, 'XL', 'super_cab', 'pickup_tub', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2178, 'Kerb weight with heaviest factory optional equipment', 3230, 6350, 1490, 1959, 1052, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XL, XLT 2022MY Vehicle Masses: 4x4 Super Cab Pick-up', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Minimum kerb weight 2,091 kg gives 1,139 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xlt-super-pickup-biturbo', 'Ford', 'Ranger', 2022, NULL, 'XLT', 'super_cab', 'pickup_tub', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2189, 'Kerb weight with heaviest factory optional equipment', 3230, 6350, 1450, 1959, 1041, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XL, XLT 2022MY Vehicle Masses: 4x4 Super Cab Pick-up XLT', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Minimum kerb weight 2,145 kg gives 1,085 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xl-double-pickup-singleturbo', 'Ford', 'Ranger', 2022, NULL, 'XL', 'double_cab', 'pickup_tub', '4x4 part-time', '2.0L single-turbo diesel; 125 kW / 405 Nm', '6-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2201, 'Kerb weight with heaviest factory optional equipment', 3250, 6200, 1450, 1959, 1049, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XL 2022MY Vehicle Masses: 4x4 Double Cab Pick-up 2.0L Single Turbo', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Minimum kerb weight 2,118 kg gives 1,132 kg payload; conservative figure stored. Lower GCM of 6,200 kg applies to the single-turbo engine. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xl-double-pickup-biturbo', 'Ford', 'Ranger', 2022, NULL, 'XL', 'double_cab', 'pickup_tub', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2227, 'Kerb weight with heaviest factory optional equipment', 3250, 6350, 1490, 1959, 1023, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XL 2022MY Vehicle Masses: 4x4 Double Cab Pick-up 2.0L Bi-Turbo', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Minimum kerb weight 2,143 kg gives 1,107 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xls-double-pickup-biturbo', 'Ford', 'Ranger', 2022, NULL, 'XLS', 'double_cab', 'pickup_tub', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2272, 'Kerb weight with heaviest factory optional equipment', 3230, 6350, 1450, 1959, 958, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XLS, XLT 2022MY Vehicle Masses: 4x4 Double Cab Pick-up XLS', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Minimum kerb weight 2,151 kg gives 1,079 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xlt-double-pickup-biturbo', 'Ford', 'Ranger', 2022, NULL, 'XLT', 'double_cab', 'pickup_tub', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2271, 'Kerb weight with heaviest factory optional equipment', 3230, 6350, 1450, 1959, 959, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XLS, XLT 2022MY Vehicle Masses: 4x4 Double Cab Pick-up XLT 2.0L Bi-Turbo', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Minimum kerb weight 2,197 kg gives 1,033 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-xlt-double-pickup-v6', 'Ford', 'Ranger', 2022, NULL, 'XLT', 'double_cab', 'pickup_tub', '4x4 full-time', '3.0L V6 turbo-diesel; 184 kW / 600 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2331, 'Kerb weight with heaviest factory optional equipment', 3280, 6400, 1490, 1959, 949, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 XLS, XLT 2022MY Vehicle Masses: 4x4 Double Cab Pick-up XLT 3.0L V6', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Minimum kerb weight 2,256 kg gives 1,024 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-sport-double-pickup-biturbo', 'Ford', 'Ranger', 2022, NULL, 'Sport', 'double_cab', 'pickup_tub', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2288, 'Kerb weight with heaviest factory optional equipment', 3230, 6350, 1450, 1959, 942, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 Sport, Wildtrak, Raptor 2022MY Vehicle Masses: Sport 2.0L Bi-Turbo', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Minimum kerb weight 2,206 kg gives 1,024 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-sport-double-pickup-v6', 'Ford', 'Ranger', 2022, NULL, 'Sport', 'double_cab', 'pickup_tub', '4x4 full-time', '3.0L V6 turbo-diesel; 184 kW / 600 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2346, 'Kerb weight with heaviest factory optional equipment', 3280, 6400, 1490, 1959, 934, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 Sport, Wildtrak, Raptor 2022MY Vehicle Masses: Sport 3.0L V6', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Lowest published payload in the Ranger diesel range. Minimum kerb weight 2,264 kg gives 1,016 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-wildtrak-double-pickup-biturbo', 'Ford', 'Ranger', 2022, NULL, 'Wildtrak', 'double_cab', 'pickup_tub', '4x4 part-time', '2.0L bi-turbo diesel; 154 kW / 500 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2341, 'Kerb weight with heaviest factory optional equipment', 3280, 6350, 1490, 1959, 939, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 Sport, Wildtrak, Raptor 2022MY Vehicle Masses: Wildtrak 2.0L Bi-Turbo', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Minimum kerb weight 2,271 kg gives 1,009 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-wildtrak-double-pickup-v6', 'Ford', 'Ranger', 2022, NULL, 'Wildtrak', 'double_cab', 'pickup_tub', '4x4 full-time', '3.0L V6 turbo-diesel; 184 kW / 600 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2399, 'Kerb weight with heaviest factory optional equipment', 3350, 6400, 1490, 1959, 951, 'Published payload based on kerb weight', 3500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 Sport, Wildtrak, Raptor 2022MY Vehicle Masses: Wildtrak 3.0L V6', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Highest GVM (3,350 kg) in the Ranger range. Minimum kerb weight 2,329 kg gives 1,021 kg payload; conservative figure stored. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.'),
  ('ford-ranger-2022my-4x4-raptor-double-pickup-ecoboost', 'Ford', 'Ranger', 2022, NULL, 'Raptor', 'double_cab', 'pickup_tub', '4x4 full-time', '3.0L V6 twin-turbo EcoBoost petrol; 292 kW / 583 Nm', '10-speed automatic', NULL, 'Standard light-vehicle licence subject to final configuration', NULL, 2475, 'Kerb weight with heaviest factory optional equipment', 3130, 5370, 1520, 1700, 655, 'Derived: GVM minus kerb weight. Ford does not publish a kerb-based payload for Raptor and instead quotes 708 kg from tare weight (2,422 kg)', 2500, NULL, NULL, NULL, NULL, 'ford-ranger-2022my-au', '4x4 Sport, Wildtrak, Raptor 2022MY Vehicle Masses: Raptor', 'source_verified', 0, 'Tub-compatible camper only unless engineered tray conversion is verified. Worst slide-on candidate in the range: lowest GVM (3,130 kg), lowest GCM (5,370 kg), lowest braked towing (2,500 kg) and heaviest kerb weight. The stored 655 kg is the conservative kerb-based derivation, not the Ford tare-based 708 kg figure. Petrol, not diesel. This row describes the 2022MY vehicle specifically and remains valid for it; the 2026.50MY range is recorded separately.');
